// frozen into the row at confirm time, so a later settings edit cannot change
// what the human authorized.
func (q *Queries) SetImportJobPlan(ctx context.Context, arg SetImportJobPlanParams) (ImportJob, error) {
	row := q.db.QueryRow(ctx, setImportJobPlan,
		arg.ID,
		arg.WorkspaceID,
		arg.Status,
		arg.Plan,
		arg.Mapping,
	)
	var i ImportJob
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.ConnectionID,
		&i.Source,
		&i.Status,
		&i.Scope,
		&i.Plan,
		&i.Mapping,
		&i.Totals,
		&i.Failures,
		&i.ArtifactID,
		&i.CreatedBy,
		&i.StartedAt,
		&i.FinishedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

